ALTER TABLE chat_conversations ADD COLUMN IF NOT EXISTS artist_workspace_id BIGINT UNSIGNED NULL AFTER user_id, ADD INDEX IF NOT EXISTS idx_chat_conversations_artist_workspace (artist_workspace_id,updated_at);
